def matches_op(doc, query):
    ops = {'$gt': lambda a, b: a > b, '$lt': lambda a, b: a < b,
           '$gte': lambda a, b: a >= b, '$lte': lambda a, b: a <= b}
    for key, cond in query.items():
        if key not in doc:
            return False
        if isinstance(cond, dict):
            if not all(ops[op](doc[key], v) for op, v in cond.items()):
                return False
        elif doc[key] != cond:
            return False
    return True

def count_matching(docs, query):
    ops = {'$gt': lambda a, b: a > b, '$lt': lambda a, b: a < b,
           '$gte': lambda a, b: a >= b, '$lte': lambda a, b: a <= b}
    def ok(doc):
        for key, cond in query.items():
            if key not in doc:
                return False
            if isinstance(cond, dict):
                if not all(ops[o](doc[key], v) for o, v in cond.items()):
                    return False
            elif doc[key] != cond:
                return False
        return True
    return sum(1 for d in docs if ok(d))

