def update_one(docs, query, update):
    for doc in docs:
        if all(doc.get(k) == v for k, v in query.items()):
            doc.update(update['$set'])
            return 1
    return 0

def delete_one(docs, query):
    for doc in docs:
        if all(doc.get(k) == v for k, v in query.items()):
            docs.remove(doc)
            return 1
    return 0
